head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedCellOverColor]<br/>마우스 포인터가 포커스된 Body Row 에 오버될때 포커스된 Body Cell 의 배경색으로 적용될 색상. rowMouseOver=true 이고 focusMode='cell','both' 인 경우 동작.",
    "validation" : [
        "포커스된 Body Row 에 마우스가 오버되면 selectedCellOverColor, selectedRowOverColor 가 focusMode 속성에 따라 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - rowMouseOver 는 본 샘플 검증 전제이므로 "true" 하드코딩, 옵션으로 노출하지 않음
    //  - focusMode 는 con_focusMode 정적 select 에서 선택 (미설정""/cell/both — selectedCellOverColor 는 cell/both 에서 동작)
    //  - selectedCellColor / selectedRowColor 는 포커스 상태 가시화를 위해 기본 색을 부여
    let properties = {
        dataList             : "data:dlt_bind",
        rowMouseOver         : "true",
        focusMode            : con_focusMode.getValue(),
        selectedCellColor    : "yellow",
        selectedRowColor     : "lightgreen",
        selectedCellOverColor: con_selectedCellOverColor.getValue(),
        selectedRowOverColor : con_selectedRowOverColor.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbodymouseover"]);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblMode = (properties.focusMode === '') ? '미설정(기본값 cell)' : properties.focusMode;
    let lblCellOver = (properties.selectedCellOverColor === '') ? '미설정' : properties.selectedCellOverColor;
    let lblRowOver = (properties.selectedRowOverColor === '') ? '미설정' : properties.selectedRowOverColor;
    $c.gcm.createLabel('label="rowMouseOver=true (고정) / focusMode=' + lblMode + ' / selectedCellOverColor=' + lblCellOver + ' / selectedRowOverColor=' + lblRowOver + ' 로 GridView 생성"', '', 'label1');

    // dataList 생성 (헬퍼와 동일하게 col1~col4 컬럼 구성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// 지정한 Body Cell 을 포커스시키는 사전상태 설정 (마우스 오버는 사용자 동작으로 수행)
//  - rowIndex/colIndex 는 par_ 콤보에서 선택
scwin.btn_setFocusedCell_onclick = function () {
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);
    let colIndex = parseInt(par_colIndex.getValue(), 10);

    // DataList currentRow 정합성 유지
    dlt_bind.setRowPosition(rowIndex);
    target1.setFocusedCell(rowIndex, colIndex);

    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 설정] Cell(" + rowIndex + "," + colIndex + ") 포커스. 해당 Row 에 마우스를 오버하세요.");
}



// 포커스된 Cell 의 Row 에 마우스가 오버되면 자동 출력 (onbodymouseover)
//  - focusMode 분기에 따라 selectedCellOverColor / selectedRowOverColor 적용 결과를 확인
//    · cell : 포커스 Cell 에 selectedCellOverColor 적용 / 동일 Row 다른 Cell 은 over color 미적용(기본 row-over 색, selectedRowOverColor 미적용)
//    · both : 포커스 Cell 에 selectedCellOverColor 적용 / 동일 Row 다른 Cell 에 selectedRowOverColor 적용
//  - cell/both 모두 [포커스 Cell 배경색] + [동일 Row 다른 Cell 배경색] 두 줄을 출력하여 적용 범위 차이를 대비
//  - 각 영역 td 의 실제 적용 배경색(computed backgroundColor)을 setReturnValue 로 자동 출력
scwin.target1_onbodymouseover = function (info) {
    let rowIndex = target1.getFocusedRowIndex();
    let colIndex = target1.getFocusedColumnIndex();
    // 포커스된 Cell 이 없으면 출력하지 않음
    if (rowIndex === null || rowIndex === undefined || rowIndex < 0 ||
        colIndex === null || colIndex === undefined || colIndex < 0) {
        return;
    }

    // 포커스된 Cell 의 Row 에 오버된 경우에만 출력
    if (info.rowIndex !== rowIndex) {
        return;
    }

    let mode = con_focusMode.getValue();
    let effectMode = (mode === '') ? 'cell' : mode;   // 미설정 시 기본값 cell

    let getColor = function (r, c) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
        return td ? window.getComputedStyle(td).backgroundColor : "(cell 없음)";
    };

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbodymouseover (focusMode=" + effectMode + ", Row " + rowIndex + " 오버)=====");

    // 포커스 행의 다른 셀 : 포커스 셀과 같은 row, 다른 column 으로 결정적 선택
    let otherCol = (colIndex === 0) ? 1 : 0;

    // [포커스 Cell] : cell/both 모두 selectedCellOverColor 적용 기대
    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 Cell(" + rowIndex + "," + colIndex + ") 배경색] " + getColor(rowIndex, colIndex));

    // [동일 Row 다른 Cell] : both → selectedRowOverColor 적용 / cell → over color 미적용(기본 row-over 색)
    wf_body_bottom.getObj("scwin").setReturnValue("[동일 Row 다른 Cell(" + rowIndex + "," + otherCol + ") 배경색] " + getColor(rowIndex, otherCol));
}
